function Test-MatchInZone {
    param([string]$MatchValue, [array]$Words, [array]$Zones, [int]$PageNum)
    if (-not $Zones -or $Zones.Count -eq 0) { return $true }  # no zones = no constraint
    foreach ($w in $Words) {
        if ($w.text -like "*$MatchValue*" -or $MatchValue -like "*$($w.text)*") {
            $wxFrac = $w.x / $pw; $wyFrac = $w.y / $ph
            $wwFrac = $w.w / $pw; $whFrac = $w.h / $ph
            foreach ($z in $Zones) {
                # AABB intersect of the word box against the zone
                if ($wxFrac + $wwFrac -ge $z.x -and $wxFrac -le ($z.x + $z.w) -and
                    $wyFrac + $whFrac -ge $z.y -and $wyFrac -le ($z.y + $z.h)) {
                    return $true
                }
            }
        }
    }
    return $false
}

function Get-PdfTextInRegion {
    # Extract text within a rectangular region of one page using pdftotext.
    param([string]$PdftotextExe, [string]$PdfPath, [int]$Page, [int]$X, [int]$Y, [int]$W, [int]$H)
    if (-not $PdftotextExe) { return "" }
    $tmp = [System.IO.Path]::GetTempFileName() + ".txt"
    try {
        & $PdftotextExe -f $Page -l $Page -x $X -y $Y -W $W -H $H -layout -enc UTF-8 "$PdfPath" "$tmp" 2>&1 | Out-Null
        if (Test-Path $tmp) {
            $text = [System.IO.File]::ReadAllText($tmp, [System.Text.UTF8Encoding]::new($false))
            return $text.Trim()
        }
    } finally { ... }
    return ""
}

function Resolve-TaggedZoneRect {
    # Re-find a tag (anchor) on the document at run-time and compute the value
    # rectangle relative to it. This makes tagged zones float with their label.
    param([string]$PdfPath, [int]$Page = 1, [string]$AnchorText,
          [bool]$AnchorIsRegex = $false, $Rel = $null, [bool]$ScanAllPages = $true)
    $bboxes = Get-PdfTextBboxByPage -PdftotextExe $pdftotextExe -PdfPath $PdfPath
    foreach ($pg in $pagesToSearch) {
        $aRect = Find-AnchorRectFrac -Words $bboxes[$pg] -AnchorText $AnchorText -IsRegex $AnchorIsRegex ...
        if (-not $aRect) { continue }
        $vx = [Math]::Max(0.0, [Math]::Min(1.0, $aRect.x + $dx))
        $vy = [Math]::Max(0.0, [Math]::Min(1.0, $aRect.y + $dy))
