function Write-IndexXml {
    # Emit an OnBase XML Index DIP file (Foundation 24.1 schema).
    param([string]$OutPath, [string[]]$Headers, [System.Collections.IEnumerable]$Rows, [hashtable]$XmlCfg)
    ...
    foreach ($r in $Rows) {
