function Invoke-OllamaPrompt {
    param([string]$Model, [string]$Prompt, [string]$Format = "", [int]$NumCtx = 0, [int]$TimeoutSec = 0)
    $ollamaHost = if ($AppSettings.ollamaHost) { $AppSettings.ollamaHost } else { "http://127.0.0.1:11434" }
    if ($NumCtx -le 0) { $NumCtx = ... 32768 }
    $body = @{ model = $Model; prompt = $Prompt; stream = $false; options = @{ num_ctx = $NumCtx } }
    if ($Format) { $body.format = $Format }
    try {
        $json = $body | ConvertTo-Json -Compress -Depth 5
        $resp = Invoke-RestMethod -Uri "$ollamaHost/api/generate" -Method Post -Body $json -ContentType "application/json" -TimeoutSec $TimeoutSec
        return $resp.response
    } catch { Write-Log "  Ollama error: $($_.Exception.Message)"; return $null }
}

function New-SearchablePdfFromImages {
    # Combine scanned page images into ONE searchable PDF via bundled Tesseract.
    param([string[]]$ImagePaths, [string]$OutPdf, [string]$Lang = "eng")
    $tess = Get-TesseractExe
    if (-not $tess) { return @{ ok = $false; error = "Tesseract not found ..." } }
    $listFile = [System.IO.Path]::GetTempFileName()
    try {
        Set-Content -LiteralPath $listFile -Value ($ImagePaths -join "`n") -Encoding ascii
        $outBase = [System.IO.Path]::Combine(..., [System.IO.Path]::GetFileNameWithoutExtension($OutPdf))
        $tessdata = Join-Path $ScriptDir "tesseract\tessdata"
        $env:TESSDATA_PREFIX = $tessdata
        & $tess $listFile $outBase "-l" $Lang "pdf" 2>&1 | Out-Null
        if (Test-Path "$outBase.pdf") { return @{ ok = $true; pdf = "$outBase.pdf" } }
    } catch { ... } finally { Remove-Item -LiteralPath $listFile -Force ... }
}

