static void Main()
{
    string exeDir = AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');
    string appDir = Path.Combine(exeDir, "Application");
    string serverPs = Path.Combine(appDir, "AutoPDF-Server.ps1");
    ReadSettings(Path.Combine(appDir, "autopdf-settings.json"));
    string url = "http://127.0.0.1:" + Port + "/";

    // Already running? Just open it.
    if (IsUp(url)) { OpenBrowser(url); return; }
    ...
    StartServerHidden(serverPs, appDir);
    for (int i = 0; i < 80 && !ready; i++) {
        Thread.Sleep(500);
        if (IsUp(url)) ready = true;
    }
    if (ready) OpenBrowser(url);
}

static void StartServerHidden(string serverPs, string appDir)
{
    // Prefer PowerShell 7 (pwsh) if present, else Windows PowerShell 5.1.
    string ps = "powershell.exe";
    ... if (pwsh found) ps = "pwsh.exe";
    var psi = new ProcessStartInfo(ps,
        "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \"" + serverPs + "\"")
    {
        WorkingDirectory = appDir,
        UseShellExecute = false,
        CreateNoWindow = true,
        WindowStyle = ProcessWindowStyle.Hidden
    };
    psi.EnvironmentVariables["AUTOPDF_NO_BROWSER"] = "1";
    Process.Start(psi);
}

